    const openScaleListDlg = () => optSub('Default Scale List', (b) => {
      const list = el('div', 'ctype-list opt-scalelist');
      const paint = () => {
        list.innerHTML = '';
        Nasj.scaleList.all().forEach((s) => {
          const row = el('div', 'ctype-row' + (Nasj.scaleList.isCustom(s.label) ? ' opt-scale-custom' : ''),
            esc(s.label));
          row.addEventListener('click', () => {
            list.querySelectorAll('.sel').forEach((n) => n.classList.remove('sel'));
            row.classList.add('sel');
          });
          list.appendChild(row);
        });
      };
      paint();
      b.appendChild(el('div', 'plab', 'Scales in the list (the status bar reads this):'));
      b.appendChild(list);
      const addRow = el('div', 'prow');
      const nameIn = el('input', 'pnum');
      nameIn.placeholder = 'Name (1:250)';
      nameIn.style.width = '90px';
      const facIn = el('input', 'pnum');
      facIn.placeholder = 'Units per paper unit';
      facIn.style.width = '120px';
      addRow.appendChild(nameIn);
      addRow.appendChild(facIn);
      addRow.appendChild(subBtn('Add', () => {
        const f = Number(facIn.value);
        const nm = nameIn.value.trim();
        if (!nm || !isFinite(f) || f <= 0) { Nasj.toast('A scale needs a name and its units per paper unit.'); return; }
        Nasj.scaleList.add(nm, f);
        nameIn.value = '';
        facIn.value = '';
        paint();
      }));
      addRow.appendChild(subBtn('Delete', () => {
        const sel = list.querySelector('.sel');
        if (!sel) return;
        if (!Nasj.scaleList.isCustom(sel.textContent)) {
          Nasj.toast('A default scale cannot be deleted — Reset clears the added ones.');
          return;
        }
        Nasj.scaleList.remove(sel.textContent);
        paint();
      }));
      addRow.appendChild(subBtn('Reset', () => { Nasj.scaleList.reset(); paint(); }));
      b.appendChild(addRow);
    });

