        g2.appendChild(specBtn('Digital Signatures…'));
        g2.appendChild(oChk('Display digital signature information', 'sigInfo'));
        L.appendChild(g2);
        const g3 = grp('File Open');
        g3.appendChild(oNum('Number of recently-used files', 'recentFiles'));
        g3.appendChild(oChk('Display full path in title', 'fullPath'));
